INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('517a4a58cbf4aec9861f','Amedex 2023.pdf','1500','Mixed/Unclassified','A 17-year-old boy is brought to your office by his mother for evaluation. History revleas that he had
always been a good student until the age 15 when his grades began dropping. His mother has also
noticed that he has stopped socializing with friends and begun spending more time alone in his
room. He dropped the school earlier this year due to poor school performance. His mother reports
that he has been trying to home-school him, but he does not seem interested in learning. Days go
before he takes bath and he does not seem to care about his appearance. What concerns the
mother most and has led her to bringing him to see a psychiatrist is the fact that for the past 2
months, she has overheard him having what sounds like conversations with someone imaginary in
his room. Which one of the following could be the most likely diagnosis?','{"A":"Major depressive disorder.","B":"Substance abuse disorder.","C":"Schizophrenia.","D":"Brief psychotic disorder.","E":"Schizophreniform disorder."}','C','The scenario, describes a condition of 2-year duration, with social withdrawal as the initiating event
(dropping grades and poor school performance), refusing to home-learn, unkempt appearance, and
more importantly conversations with an imaginary individual that is a strong pointer towards
hallucinations. These features are characteristic of schizophrenia as the most likely diagnosis.
To establish the diagnosis of schizophrenia the following criteria should be met:
Two (or more) of the following symptoms:
Hallucinations
Delusions
Disorganized speech
Grossly disorganized or catatonic behavior
Negative symptoms
AND
The symptoms are severe enough to cause significant social or occupation disability
AND
The symptoms have lasted for at least 6 months
AND
Other psychotic conditions such as schizophreniform disorder, brief psychotic episode, etc.
are excluded','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-03c8966b648b","duplicate_sources":[{"record_id":"517a4a58cbf4aec9861f","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1500,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"517a4a58cbf4aec9861f","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1500,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 17-year-old boy is brought to your office by his mother for evaluation. History revleas that he had\nalways been a good student until the age 15 when his grades began dropping. His mother has also\nnoticed that he has stopped socializing with friends and begun spending more time alone in his\nroom. He dropped the school earlier this year due to poor school performance. His mother reports\nthat he has been trying to home-school him, but he does not seem interested in learning. Days go\nbefore he takes bath and he does not seem to care about his appearance. What concerns the\nmother most and has led her to bringing him to see a psychiatrist is the fact that for the past 2\nmonths, she has overheard him having what sounds like conversations with someone imaginary in\nhis room. Which one of the following could be the most likely diagnosis?","options":{"A":"Major depressive disorder.","B":"Substance abuse disorder.","C":"Schizophrenia.","D":"Brief psychotic disorder.","E":"Schizophreniform disorder."},"source_answer":"C","source_explanation":"The scenario, describes a condition of 2-year duration, with social withdrawal 