INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('6d5773f2836682a5268b','Amedex 2023.pdf','1515','Mixed/Unclassified','A 32-year-old woman presents to your practice with complaint of back pain, felt between her
shoulder blades. Her past medical history is remarkable for anorexia nervosa for 16 years. On
examination, she is severely emaciated, weighs 38 kg and has a body mass index (BMI) of 14
kg/m2. Palpation of the interscapular region elicits tenderness over the vertebral column. Which
one of the following could be the most likely diagnosis?','{"A":"Vertebral compression fracture.","B":"Pneumonia.","C":"Pulmonary embolism.","D":"Pericardial effusion.","E":"Metastatic bone lesion."}','A','Patients with longstanding anorexia nervosa (>6 months) are at significantly increased risk of
pathological fractures due to osteopenia and osteoporosis caused by malnutrition and estrogen
deficiency.
Osteopenia and osteoporosis is a complication of long-standing anorexia nervosa. These changes
are often treated once anorexia nervosa are successfully treated and adequate weight gain is
obtained. Vertebral column is the most common site of pathologic fractures due to osteoporosis.
In this patient with long-standing anorexia nervosa, the pain and tenderness over thoracic vertebrae
makes compression fracture the most likely diagnosis.
Pneumonia (option B), pulmonary embolism (option C), and pericardial effusion (option D) may be
associated with referred pain to the back, but there is be no tenderness.
Metastatic bone lesions (option E) can cause pathologic fractures; however, with the presence of
anorexia nervosa as a significant risk factor on one hand, and no pointers towards an underlying
primary malignancy on the other, metastatic bone disease is less likely.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"892","duplicate_group_id":"exact-4afb930e5dd2","duplicate_sources":[{"record_id":"6d5773f2836682a5268b","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1515,"source_qid":"892"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"6d5773f2836682a5268b","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1515,"source_qid":"892","domain_hint":"Mixed/Unclassified","stem":"A 32-year-old woman presents to your practice with complaint of back pain, felt between her\nshoulder blades. Her past medical history is remarkable for anorexia nervosa for 16 years. On\nexamination, she is severely emaciated, weighs 38 kg and has a body mass index (BMI) of 14\nkg/m2. Palpation of the interscapular region elicits tenderness over the vertebral column. Which\none of the following could be the most likely diagnosis?","options":{"A":"Vertebral compression fracture.","B":"Pneumonia.","C":"Pulmonary embolism.","D":"Pericardial effusion.","E":"Metastatic bone lesion."},"source_answer":"A","source_explanation":"Patients with longstanding anorexia nervosa (>6 months) are at significantly increased risk of\npathological fractures due to osteopenia and osteoporosis caused by malnutrition and estrogen\ndeficiency.\nOsteopenia and osteoporosis is a complication of long-standing anorexia nervosa. These changes\nare often treated once anorexia nervosa are successfully treated and adequate weight gain is\nobtained. Vertebral column is the most common site of pathologic fractures due to osteoporosis.\nIn this patient with long-standing anorexia nervosa, the pain and tenderness over thoracic vertebrae\nmakes compression fracture the most likely diagnosis.\nPneumonia (option B), pulmonary embolism (option C), and pericardial effusion (option D) may be\nassociated with referred pain to the back, but there is be no tenderness.\nMetastatic bone lesions (option E) can cause pathologic fractures; however, with the presence of\nanorexia nervosa as a significant risk factor on one hand, and no pointers towards an underlying\nprimary malignancy on the other, metastatic bone disease is less likely.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"4afb930e5dd2c1bad557352d5e4bfc8b04c45fc7","duplicate_group_id":"exact-4afb930e5dd2","duplicate_sources":[{"record_id":"6d5773f2836682a5268b","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1515,"source_qid":"892"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,a