INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('405dbeb49a3d5bd0cec1','src-v294-687f312c',NULL,'1630','Mixed/Unclassified','Mixed/Unclassified','Mixed/Unclassified','AMC MCQ','A 16-year-old boy presents to your GP clinic with complaint of recent decrease in school
performance. He broken up with his girlfriend 3 weeks ago. He has been suffering from lack of
energy and sleep disturbances, and feels like crying almost all the time. Which one of the following
would be the most appropriate next step in management?',NULL,'A','This young boy has presented with symptoms suggestive of depression after an identifiable
stressor (the breakup). He has the criteria for ‘adjustment disorder’ as the most likely diagnosis.
The DSM-5 diagnostic criteria for adjustment disorder are as follows:
Emotional or behavioral symptoms develop in response to an identifiable stressor or
stressors within 3 months of the onset of the stressor(s) plus either or both of (1) marked
distress that is out of proportion to the severity or intensity of the stressor, even when
external context and cultural factors that might influence symptom severity and presentation
are taken into account and/or (2) significant impairment in social, occupational, or other
areas of functioning.
The stress-related disturbance does not meet criteria for another mental disorder and is not
merely an exacerbation of a preexisting mental disorder.
The symptoms do not represent normal bereavement
After the termination of the stressor (or its consequences), the symptoms persist for no
longer than an additional 6 months
Royal College of Australian General Practitioners (RACGP) has proposed a model for interacting
with patients with psychological distress and disturbances regardless of the underlying etiology.
This approach model consists of three steps:
STEP 1- Establishing rapport using active listening and empathy, non-directional supportive
psychotherapy, and psycho-education. Then if required:
STEP 2- Cognitive behavioral therapy (CBT), interpersonal psychotherapy and interpersonal
counselling, structured problem solving, behavioral therapy, and family therapy. Then if
required:
STEP 3- Intensive therapy (e.g., use of medications)',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,NULL,'2023','v2.9.4',1,'text','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-8bb706ee8590","duplicate_sources":[{"record_id":"405dbeb49a3d5bd0cec1","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1630,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,'needs_verification','[]','high') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_year=excluded.source_year,import_version=excluded.import_version,active=1,options_mode=excluded.options_mode,provenance_json=excluded.provenance_json,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk;
