INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('814e2ab46cad71f37d38','Amedex 2023.pdf','1717','Mixed/Unclassified','A junior doctor in the hospital had a needle stick injury while setting up a line for intravenous fluids. The patient status for hepatitis B is unknown. The doctor has no history of
previous hepatitis B vaccination. A blood sample of the doctor is sent to laboratory for hepatitis B serology which came back positive for HBsAg. Which one of the following is the
next best step in management?','{"A":"Give immunoglobulin.","B":"Give hepatitis B vaccine and immunoglobulin.","C":"Counselling and follow-up.","D":"Lamivudine.","E":"Give hepatitis B vaccine."}','C','This health care worker had a needle stick injury and blood test came back positive for hepatitis B surface antigen meaning that he has hepatitis B infection. This healthcare worker
should be counseled about the result and should have follow-up testing at 3 months and 6 months. If the blood tests remain positive for hepatitis surface antigen beyond 6 months,
the patient should be referred to specialist.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"316","duplicate_group_id":"exact-1d954f3d8129","duplicate_sources":[{"record_id":"814e2ab46cad71f37d38","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1717,"source_qid":"316"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"814e2ab46cad71f37d38","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1717,"source_qid":"316","domain_hint":"Mixed/Unclassified","stem":"A junior doctor in the hospital had a needle stick injury while setting up a line for intravenous fluids. The patient status for hepatitis B is unknown. The doctor has no history of\nprevious hepatitis B vaccination. A blood sample of the doctor is sent to laboratory for hepatitis B serology which came back positive for HBsAg. Which one of the following is the\nnext best step in management?","options":{"A":"Give immunoglobulin.","B":"Give hepatitis B vaccine and immunoglobulin.","C":"Counselling and follow-up.","D":"Lamivudine.","E":"Give hepatitis B vaccine."},"source_answer":"C","source_explanation":"This health care worker had a needle stick injury and blood test came back positive for hepatitis B surface antigen meaning that he has hepatitis B infection. This healthcare worker\nshould be counseled about the result and should have follow-up testing at 3 months and 6 months. If the blood tests remain positive for hepatitis surface antigen beyond 6 months,\nthe patient should be referred to specialist.","source_answer_status":"present","current_answer":null,"current_answer_status":"n