INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('48f442042c06286206c4','Amedex 2023.pdf','1725','Mixed/Unclassified','While establishing an intravenous live, a 26-year-old nurse sustains a needle stick injury from a patient who is known to be HBsAg positive. She is 15 weeks pregnant. Serologic tests of nurse shows both HBsAg and HBsAb are negative. Which one of
the following is the most appropriate management for her?','{"A":"Reassure her as she is HBsAg negative.","B":"A full course of hepatitis B vaccine.","C":"Hepatitis B immunoglobulin (HBIG).","D":"A full course of hepatitis B vaccine and HBIG.","E":"Repeat HBsAg and HBsAb in 3 months."}','D','Post-exposure prophylaxis for hepatitis B during pregnancy is the same for non-pregnant persons and follows the same general guidelines.
After exposure to hepatitis B, serology testing for the person who has had the exposure should be performed urgently. A negative HBsAg and a HBsAb titer of >10IU/mL indicates sufficient immunity against hepatitis B, and no further action is
required.
With HBsAb titers <10 (and HBsAg negative), the person has not enough immunity, and should receive both hepatitis B vaccine and HBIG within 72 hours of exposure, ideally within 24 hours. Vaccine should also be given at 1 and 6 months after the
first dose (0, 1 and 6 months). Serology testing should be repeated in 3 months. If the mother is found to be HBsAg positive despite prophylaxis, the baby should receive vaccine and HBIG within 12 hours of birth.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"1097","duplicate_group_id":"exact-1b17a8aa7695","duplicate_sources":[{"record_id":"48f442042c06286206c4","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1725,"source_qid":"1097"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"48f442042c06286206c4","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1725,"source_qid":"1097","domain_hint":"Mixed/Unclassified","stem":"While establishing an intravenous live, a 26-year-old nurse sustains a needle stick injury from a patient who is known to be HBsAg positive. She is 15 weeks pregnant. Serologic tests of nurse shows both HBsAg and HBsAb are negative. Which one of\nthe following is the most appropriate management for her?","options":{"A":"Reassure her as she is HBsAg negative.","B":"A full course of hepatitis B vaccine.","C":"Hepatitis B immunoglobulin (HBIG).","D":"A full course of hepatitis B vaccine and HBIG.","E":"Repeat HBsAg and HBsAb in 3 months."},"source_answer":"D","source_explanation":"Post-exposure prophylaxis for hepatitis B during pregnancy is the same for non-pregnant persons and follows the same general guidelines.\nAfter exposure to hepatitis B, serology testing for the person who has had the exposure should be performed urgently. A negative HBsAg and a HBsAb titer of >10IU/mL indicates sufficient immunity against hepatitis B, and no further action is\nrequired.\nWith HBsAb titers <10 (and HBsAg negative), the person has not enough immunity, and should receive both hepatitis B vaccine and HBIG within 72 hours of exposure, ideally within 24 hours. Vaccine should also be given at 1 and 6 months after the\nfirst dose (0, 1 and 6 months). Serology testing should be repeated in 3 months. If the mother is found to be HBsAg positive despite prophylaxis, the baby should receive vaccine and HBIG within 12 hours of birth.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","dose","guideline","management","pregnan","prophyl","vaccin"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"1b17a8aa76954efd5f013680d0b1c9e886f3b44c","duplicate_group_id":"exact-1b17a8aa7695","duplicate_sources":[{"record_id":"48f442042c06286206c4","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1725,"source_qid":"1097"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,i