INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('cce7044778ae2e3170ef','Amedex 2023.pdf','1740','Mixed/Unclassified','A nurse at your clinic sustains a needle stick injury at workplace. She was previously vaccinated for hepatitis B. Her anti HBs antibody is measured and is below 10 mIU/ml. The
patient is known to be HBsAg positive. Which one of the following is the most appropriate next step?','{"A":"Hepatitis B vaccine.","B":"Hepatitis B vaccine and immunoglobulin.","C":"Hepatitis B serology.","D":"Reassure and follow up.","E":"No prophylaxis is needed."}','B','Post-exposure prophylaxis for hepatitis B (hepatitis B vaccine and immunoglobulin) is recommended in the following situations:
The exposed person has been vaccinated in the past and post-vaccination anti-HBs level is below 10mIU/ml
Unvaccinated exposed individuals
Unknown vaccination status of the exposed person
In previously vaccinated individuals, who have been exposed to either an HBsAg-positive source or a source whose hepatitis B status cannot be determined, post-exposure
prophylaxis is not necessary if there is a documented protective response (anti-HBs level ≥10 mIU/mL) at any time after vaccination.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"318","duplicate_group_id":"exact-b9cc99daa604","duplicate_sources":[{"record_id":"cce7044778ae2e3170ef","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1740,"source_qid":"318"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"cce7044778ae2e3170ef","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1740,"source_qid":"318","domain_hint":"Mixed/Unclassified","stem":"A nurse at your clinic sustains a needle stick injury at workplace. She was previously vaccinated for hepatitis B. Her anti HBs antibody is measured and is below 10 mIU/ml. The\npatient is known to be HBsAg positive. Which one of the following is the most appropriate next step?","options":{"A":"Hepatitis B vaccine.","B":"Hepatitis B vaccine and immunoglobulin.","C":"Hepatitis B serology.","D":"Reassure and follow up.","E":"No prophylaxis is needed."},"source_answer":"B","source_explanation":"Post-exposure prophylaxis for hepatitis B (hepatitis B vaccine and immunoglobulin) is recommended in the following situations:\nThe exposed person has been vaccinated in the past and post-vaccination anti-HBs level is below 10mIU/ml\nUnvaccinated exposed individuals\nUnknown vaccination status of the exposed person\nIn previously vaccinated individuals, who have been exposed to either an HBsAg-positive source or a source whose hepatitis B status cannot be determined, post-exposure\nprophylaxis is not necessary if there is a documented protective response (anti-HBs level ≥10 mIU/mL) at any time after vaccination.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["prophyl","vaccin"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"b9cc99daa604cbe971a55577810bada23c743112","duplicate_group_id":"exact-b9cc99daa604","duplicate_sources":[{"record_id":"cce7044778ae2e3170ef","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1740,"source_qid":"318"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
