INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('b14633957277a1e7aea2','src-v294-687f312c',NULL,'1783','Mixed/Unclassified','Mixed/Unclassified','Mixed/Unclassified','AMC MCQ','A 57-year-old man presents to the emergency department with severe shortness of breath and
tachypnea. As a part of emergency evaluation, an arterial blood gas (ABG) analysis is performed,
the result of which are as follows:
PH: 7.2 (normal 7.35-7.45)
PaCo2: 48 (normal 35-45 mmHg)
PaO2: 50 (normal 80 -100 mmHg)
Which one of the following is the next best step in management?',NULL,'D','In case of respiratory failure, oxygen supplementation is the next best step in management. This
can be achieved either by high concentration oxygen through nasal cannulae, simple face mask,
reservoir masks or non-rebreathing masks in type I (hypoxemic respiratory failure) or low-
concentration oxygen through Venturi mask in type II (hypercarbic) respiratory failure or for those
patient at increased risk of type II respiratory failure.
As a rule, however, patients with the following conditions should be supported with assisted
mechanical ventilation, either with non-invasive measures (CPAP, BiPAP) (preferred option) or
conventional intubation or mechanical ventilation as the last resort if there is:
persistent or worsening hypoxemia despite supplemental oxygen or inability to achieve an O2
saturation above 90% OR
Worsening hypercapnia (PaCO2>50 mmHg) OR
Worsening respiratory acidosis (PH<7.25) OR
Clinical manifestations of respiratory distress such as:
Severe dyspnea
Tachypnea (RR>30)
Nasal flaring
Accessory muscle use
Tracheal tugging
Recession of suprasternal and intercostal spaces
Pulsus paradoxus
Diaphoresis
Paradoxic motion of the rib cage and abdomen',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,NULL,'2023','v2.9.4',1,'text','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-6f7acfa56e24","duplicate_sources":[{"record_id":"b14633957277a1e7aea2","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1783,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,'needs_verification','[]','medium') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_year=excluded.source_year,import_version=excluded.import_version,active=1,options_mode=excluded.options_mode,provenance_json=excluded.provenance_json,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk;
