INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('4ae0d0fcc14af8ce1f97','Amedex 2023.pdf','1806','Mixed/Unclassified','A 27-year-old asthmatic man presents to the Emergency Department with sudden onset of right-
sided pleuretic chest pain. On physical examination, he has a blood pressure of 120/75 mmHg,
pulse rate of 94 bpm and respiratory rate of 18 breaths per minute. Chest auscultation reveals
diminished breath and hyper-resonance in the right lung. No respiratory distress is noted. A chest
X-ray is obtained that is significant for a 20% right-sided pneumothorax. Which one of the following
will be the most appropriate next step in management?','{"A":"Admit the patient for observation.","B":"Perform thoracotomy.","C":"Needle aspiration.","D":"Water-sealed catheter thoracostomy.","E":"Discharge the patient and review in 24 hours."}','D','Pneumothorax is defined as presence of air in the pleural space. Based on the etiology,
pneumothorax can be defined as traumatic or spontaneous.
Traumatic pneumothorax is caused by blunt or penetrating chest traumas or invasive procedures
(iatrogenic) such as central vein catheterization, pleural biopsy, etc.
Spontaneous pneumothorax is the term used when the condition occurs in the absence of an
apparent trauma or procedure. Spontaneous pneumothorax is classified as primary or secondary
based on absence or presence of an underlying lung pathology or chest X-ray abnormalities.
Primary spontaneous pneumothorax (PSP) – spontaneous pneumothorax is primary if all of
following criteria are met:
There is no respiratory finding on exam except those related to the pneumothorax
There is no history of lung disease
There is no chest X-ray finding other than those related to the pneumothorax
The patient is young (≤50 years)
There is no significant history of smoking
Secondary spontaneous pneumothorax (SSP) – spontaneous pneumothorax is considered
secondary if either of the following is present:
Respiratory findings other than those related to pneumothorax
History of lung disease such as COPD (the most common cause of SSP), asthma, cystic
fibrosis sarcoidosis, TB, lung cancer, chronic bronchitis, bronchiectasis, extra- or
intrathoracic restrictive lung disease, etc
Any chest X-ray abnormality other than those related to pneumothorax
Age >50 years
Significant history of smoking','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-41f896355723","duplicate_sources":[{"record_id":"4ae0d0fcc14af8ce1f97","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1806,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"4ae0d0fcc14af8ce1f97","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1806,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 27-year-old asthmatic man presents to the Emergency Department with sudden onset of right-\nsided pleuretic chest pain. On physical examination, he has a blood pressure of 120/75 mmHg,\npulse rate of 94 bpm and respiratory rate of 18 breaths per minute. Chest auscultation reveals\ndiminished breath and hyper-resonance in the right lung. No respiratory distress is noted. A chest\nX-ray is obtained that is significant for a 20% right-sided pneumothorax. Which one of the following\nwill be the most appropriate next step in management?","options":{"A":"Admit the patient for observation.","B":"Perform thoracotomy.","C":"Needle aspiration.","D":"Water-sealed catheter thoracostomy.","E":"Discharge the patient and review in 24 hours."},"source_answer":"D","source_explanation":"Pneumothorax is defined as presence of air in the pleural space. Based on the etiology,\npneumothorax can be defined as traumatic or spontaneous.\nTraumatic pneumothorax is caused by blunt or penetrating chest traumas or invasive procedures\n(iatrogenic) such as central vein catheterization, pleural biopsy, etc.\nSpontaneous pneumothorax is the term used when the condition occurs in the absence of an\napparent trauma or procedure. Spontaneous pneumothorax is classified as primary or secondary\nbased on absence or presence of an underlying lung pathology or chest X-ray abnormalities.\nPrimary spontaneous pneumothorax (PSP) – spontaneous pneumothorax is primary if all of\nfollowing criteria are met:\nThere is no respiratory finding on exam except those related to the pneumothorax\nThere is no history of lung disease\nThere is no chest X-ray finding other than those related to the pneumothorax\nThe patient is young (≤50 years)\nThere is no significant history of smoking\nSecondary spontaneous pneumothorax (SSP) – spontaneous pneumothorax is considered\nsecondary if either of the following is present:\nRespiratory findings other than those related to pneumothorax\nHistory of lung disease such as COPD (the most common cause of SSP), asthma, cystic\nfibrosis sarcoidosis, TB, lung cancer, chronic bronchitis, bronchiectasis, extra- or\nintrathoracic restrictive lung disease, etc\nAny chest X-ray abnormality other than those related to pneumothorax\nAge >50 years\nSignificant history of smoking","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","asthma","management"],"likely_visual_question":true,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"41f8963557234897d78f192ded44b1f7b4d920ff","duplicate_group_id":"exact-41f896355723","duplicate_sources":[{"record_id":"4ae0d0fcc14af8ce1f97","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1806,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source