INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('a344126fb7864c995ddc','Amedex 2023.pdf','1810','Mixed/Unclassified','A 68-year-old woman, with history of stage IV chronic kidney disease (CKD) presents to the
Emergency Department with sudden-onset acute chest pain and shortness of breath. The chest
pain is pleuretic in nature. On examination, she has a blood pressure of 130/90 mmHg, pulse rate
of 120 bpm and respiratory rate of 24 cycles per minute. ECG shows no abnormalities. A chest X-
ray is obtained that is completely clear. Ventilation/perfusion scan is performed
showing decreased perfusion in the lower lobe of the left lung. Which one of the following is the
most appropriate next step in management?','{"A":"Low-molecular weight heparin (LMWH).","B":"Thrombolysis.","C":"CTPA.","D":"Unfractionated heparin.","E":"Warfarin."}','D','Clinical findings suggest pulmonary embolism (PE) as the most likely diagnosis. Decreased
perfusion confirms the diagnosis. V/Q scan can be reliable if there is no pre-existing underlying
lung pathology leading to misinterpretation of the result. The validity of the V/Q scan in this
scenario can be trusted as there is no abnormal finding on chest X-ray.
Although both unfractionated heparin and low-molecular weight heparin (LMWH) have about the
same efficacy for treatment of PE, unfractionated heparin is the preferred option in patients with
renal disease because LMWH is excreted renally.
(Option A) LMWH is better avoided in patients with renal disease. If LMWH is considered for
treatment, the dose should be adjusted according to glomerular filtration rate (GFR).
(Option B) Thrombolysis is reserved for selected patients with hemodynamic instability, in whom
there is no contraindication to thrombolysis.
(Option C) Since V/Q scan has already established the diagnosis, CTPA would not be required.
Furthermore, CTPA needs intravenous injection of contrast material that is contraindicated in
patients with renal impairment. This is the reason why V/Q scan has been used for the diagnosis of
PE in the first place.
(Option E) Warfarin is a part of management after INR reaches the therapeutic dose of 2-3.
Warfarin has delayed action, and has initial pro-thrombotic effects. Anticoagulation never starts
with warfarin alone.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-b378bfb05caa","duplicate_sources":[{"record_id":"a344126fb7864c995ddc","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1810,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"a344126fb7864c995ddc","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1810,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 68-year-old woman, with history of stage IV chronic kidney disease (CKD) presents to the\nEmergency Department with sudden-onset acute chest pain and shortness of breath. The chest\npain is pleuretic in nature. On examination, she has a blood pressure of 130/90 mmHg, pulse rate\nof 120 bpm and respiratory rate of 24 cycles per minute. ECG shows no abnormalities. A chest X-\nray is obtained that is completely clear. Ventilation/perfusion scan is performed\nshowing decreased perfusion in the lower lobe of the left lung. Which one of the following is the\nmost appropriate next step in management?","options":{"A":"Low-molecular weight heparin (LMWH).","B":"Thrombolysis.","C":"CTPA.","D":"Unfractionated heparin.","E":"Warfarin."},"source_answer":"D","source_explanation":"Clinical findings suggest pulmonary embolism (PE) as the most likely diagnosis. Decreased\nperfusion confirms the diagnosis. V/Q scan can be reliable if there is no pre-existing underlying\nlung pathology leading to misinterpretation of the result. The validity of the V/Q scan in this\nscenario can be trusted as there is no abnormal finding on chest X-ray.\nAlthough both unfractionated heparin and low-molecular weight heparin (LMWH) have about the\nsame efficacy for treatment of PE, unfractionated heparin is the preferred option in patients with\nrenal disease because LMWH is excreted renally.\n(Option A) LMWH is better avoided in patients with renal disease. If LMWH is considered for\ntreatment, the dose should be adjusted according to glomerular filtration rate (GFR).\n(Option B) Thrombolysis is reserved for selected patients with hemodynamic instability, in whom\nthere is no contraindication to thrombolysis.\n(Option C) Since V/Q scan has already established the diagnosis, CTPA would not be required.\nFurthermore, CTPA needs intravenous injection of contrast material that is contraindicated in\npatients with renal impairment. This is the reason why V/Q scan has been used for the diagnosis of\nPE in the first place.\n(Option E) Warfarin is a part of management after INR reaches the therapeutic dose of 2-3.\nWarfarin has delayed action, and has initial pro-thrombotic effects. Anticoagulation never starts\nwith warfarin alone.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","anticoag","dose","management","thrombol","treatment","warfarin"],"likely_visual_question":true,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"b378bfb05caae1c3da916b65354aa45accf8f20a","duplicate_group_id":"exact-b378bfb05caa","duplicate_sources":[{"record_id":"a344126fb7864c995ddc","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1810,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
