INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('a2b5ac9e2b132c2241da','Amedex 2023.pdf','1829','Mixed/Unclassified','A 34-year-old man presents to the Emergency Department with acute-onset shortness of breath.
Medical history is only remarkable for essential thrombocytosis. On examination, he has a blood
pressure of 110/70 mmHg, pulse rate of 90 bpm, respiratory rate of 22 breath per minute, and
temperature of 37.1°C. He has a BMI of 24 kg/m2. Chest radiograph is significant for a prominent
right hilum. With the provisional diagnosis of pulmonary embolism, a CT pulmonary angiogram
(CTPA) is ordered which is shown in the following photograph. Which one of the following is the
most appropriate treatment option for this patient?','{"A":"Warfarin.","B":"Unfractionated heparin or low-molecular weight heparin (LMWH).","C":"Caval filter.","D":"Thrombolytic therapy.","E":"Dabigatran."}','B','The photograph shows a filling defect in the right branch of the pulmonary artery consistent with
the diagnosis of pulmonary embolism (PE).
PE may only present with shortness of breath and tachypnea. However, other symptoms and signs
such as pleuretic chest pain, cough, tachycardia and, in severe cases, hemodynamic instability may
be present.
With confirmed PE, the patient should be started on unfractionated heparin or low-molecular
weight heparin (LMWH) as the most appropriate next step in management.
(Option A) Warfarin should be commenced within 48 hours of heparin administration and
continued for at least 3 months or more, depending on individual risk of recurrent PE or DVT in the
future.
(Option C) Inferior vena cava (IVC) filters provide a screen in the inferior vena cava, allowing blood
to pass through, while large emboli from the pelvis or lower extremities are blocked or fragmented','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-06716afa4a26","duplicate_sources":[{"record_id":"a2b5ac9e2b132c2241da","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1829,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"a2b5ac9e2b132c2241da","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1829,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 34-year-old man presents to the Emergency Department with acute-onset shortness of breath.\nMedical history is only remarkable for essential thrombocytosis. On examination, he has a blood\npressure of 110/70 mmHg, pulse rate of 90 bpm, respiratory rate of 22 breath per minute, and\ntemperature of 37.1°C. He has a BMI of 24 kg/m2. Chest radiograph is significant for a prominent\nright hilum. With the provisional diagnosis of pulmonary embolism, a CT pulmonary angiogram\n(CTPA) is ordered which is shown in the following photograph. Which one of the following is the\nmost appropriate treatment option for this patient?","options":{"A":"Warfarin.","B":"Unfractionated heparin or low-molecular weight heparin (LMWH).","C":"Caval filter.","D":"Thrombolytic therapy.","E":"Dabigatran."},"source_answer":"B","source_explanation":"The photograph shows a filling defect in the right branch of the pulmonary artery consistent with\nthe diagnosis of pulmonary embolism (PE).\nPE may only present with shortness of breath and tachypnea. However, other symptoms and signs\nsuch as pleuretic chest pain, cough, tachycardia and, in severe cases, hemodynamic instability may\nbe present.\nWith confirmed PE, the patient should be started on unfractionated heparin or low-molecular\nweight heparin (LMWH) as the most appropriate next step in management.\n(Option A) Warfarin should be commenced within 48 hours of heparin administration and\ncontinued for at least 3 months or more, depending on individual risk of recurrent PE or DVT in the\nfuture.\n(Option C) Inferior vena cava (IVC) filters provide a screen in the inferior vena cava, allowing blood\nto pass through, while large emboli from the pelvis or lower extremities are blocked or fragmented","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","management","screen","treatment","warfarin"],"likely_visual_question":true,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"06716afa4a269c4299c625c0756429edd972da0d","duplicate_group_id":"exact-06716afa4a26","duplicate_sources":[{"record_id":"a2b5ac9e2b132c2241da","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1829,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.cur