INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('aaeaebb5fea83c1caeea','Amedex 2023.pdf','1834','Mixed/Unclassified','A 65-year-old man undergoes left hemicolectomy for colon cancer. Four days after the surgery, he
suddenly develops dyspnea. On examination, he has a blood pressure of 110/76 mmHg, heat rate
of 110 bpm and respiratory rate of 22 breaths per minute. He is afebrile. Which one of the following
is the diagnostic modality of choice to confirm the diagnosis?','{"A":"Pulmonary angiography.","B":"D-dimer.","C":"Chest X-ray (CXR).","D":"ECG.","E":"MRI."}','A','In patients with risk factors for pulmonary embolism (PE), any sign and symptoms pointing
towards the diagnosis should raise suspicion against PE, and prompt investigations follow.
Imaging by V/Q scan and CTPA is the cornerstone of diagnosis of PE; however, clinical
presentations of PE such as pleuretic chest pain, tachycardia, tachypnoea, hypoxia, etc. can be
seen in a good variety of other pulmonary conditions. For this reason an appropriate clinical
diagnostic rule (CDR) should be considered if possible in an attempt to decrease unnecessary
diagnostic tests. One of the most recent and validated tools is simplified Wells score (SWS), which
takes into account a number of items to determine whether the pretest probability of PE is likely
(PE likley more than 10% ) or unlikely ( PE likley less than 10%). Patients with SWS scores of 0 and
1 have a low pretest probability versus those with SWS scores of equal to or greater than 2.
An algorithmic approach to patients with suspected PE is as follows:
With recent major surgery in history and pulse rate of 110 bpm, this patient has SWS of 2; therefore,
PE should be considered ‘likely’ in this patient. When PE is likely the next step would be imaging
studies either by V/Q scan or computed tomography CT angiography (CTPA). Generally, CTPA is
preferred over V/Q scan because is often readily available, easy to use and more convenient to the
patient. Unlike, V/Q scan, underlying lung disease evident on CXR does not significantly affect the
specificity of the tests. Besides, it can detect smaller and more distal emboli in pulmonary arterial
tree, as well as other conditions that may mimic PE. Drawbacks to this method are more radiation','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-a83151b97db4","duplicate_sources":[{"record_id":"aaeaebb5fea83c1caeea","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1834,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"aaeaebb5fea83c1caeea","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":1834,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 65-year-old man undergoes left hemicolectomy for colon cancer. Four days after the surgery, he\nsuddenly develops dyspnea. On examination, he has a blood pressure of 110/76 mmHg, heat rate\nof 110 bpm and respiratory rate of 22 breaths per minute. He is afebrile. Which one of the following\nis the diagnostic modality of choice to confirm the diagnosis?","options":{"A":"Pulmonary angiography.","B":"D-dimer.","C":"Chest X-ray (CXR).","D":"ECG.","E":"MRI."},"source_answer":"A","source_explanation":"In patients with risk factors for pulmonary embolism (PE), any sign and symptoms pointing\ntowards the diagnosis should raise suspicion against PE, and prompt investigations follow.\nImaging by V/Q scan and CTPA is the cornerstone of diagnosis of PE; however, clinical\npresentations of PE such as pleuretic chest pain, tachycardia, tachypnoea, hypoxia, etc. can be\nseen in a good variety of other pulmonary conditions. For this reason an appropriate clinical\ndiagnostic rule (CDR) should be considered if possible in an attempt to decrease unnecessary\ndiagnostic tests. One of the most recent and validated tools is simplified Wells score (SWS), which\ntakes into account a number of items to determine whether the pretest probability of PE is likely\n(PE likley more than 10% ) or unlikely ( PE likley less than 10%). Patients with SWS scores of 0 and\n1 have a low pretest probability versus those with SWS scores of equal to or greater than 2.\nAn algorithmic approach to patients with suspected PE is as follows:\nWith recent major surgery in history and pulse rate of 110 bpm, this patient has SWS of 2; therefore,\nPE should be considered ‘likely’ in this patient. When PE is likely the next step would be imaging\nstudies either by V/Q scan or computed tomography CT angiography (CTPA). Generally, CTPA is\npreferred over V/Q scan because is often readily available, easy to use and more convenient to the\npatient. Unlike, V/Q scan, underlying lung disease evident on CXR does not significantly affect the\nspecificity of the tests. Besides, it can detect smaller and more distal emboli in pulmonary arterial\ntree, as well as other conditions that may mimic PE. Drawbacks to this method are more radiation","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":true,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"a83151b97db42adddeb0d2bfad4cd06dfa5ce327","duplicate_group_id":"exact-a83151b97db4","duplicate_sources":[{"record_id":"aaeaebb5fea83c1caeea","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":1834,"source_qid":null}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=